package com.example.melonstools.data;
import com.example.melonstools.department.DepartmentPolicy;import com.google.gson.*;import net.minecraft.core.BlockPos;import net.minecraft.nbt.*;import net.minecraft.resources.ResourceKey;import net.minecraft.server.level.*;import net.minecraft.world.damagesource.DamageSource;import net.minecraft.world.level.Level;import net.minecraft.world.level.saveddata.SavedData;import java.util.*;
/** Phase 4-C: server-only death vital alerts; no client-provided private data. */
public class VitalAlertSavedData extends SavedData{public static final String DATA_NAME="melon_vital_alerts";public static final String OPEN="open",ACKNOWLEDGED="acknowledged",DISPATCHED="dispatched",RESOLVED="resolved";private final List<Alert> alerts=new ArrayList<>();private int sequence;public static VitalAlertSavedData get(ServerLevel l){return l.getDataStorage().computeIfAbsent(VitalAlertSavedData::load,VitalAlertSavedData::new,DATA_NAME);}public static VitalAlertSavedData load(CompoundTag tag){VitalAlertSavedData d=new VitalAlertSavedData();d.sequence=tag.getInt("Sequence");ListTag a=tag.getList("Alerts",Tag.TAG_COMPOUND);for(int i=0;i<a.size();i++)d.alerts.add(Alert.load(a.getCompound(i)));return d;}@Override public CompoundTag save(CompoundTag tag){tag.putInt("Sequence",sequence);ListTag a=new ListTag();for(Alert x:alerts)a.add(x.save());tag.put("Alerts",a);return tag;}private Alert byId(String id){for(Alert a:alerts)if(a.id.equals(id))return a;return null;}private static void audit(ServerPlayer p,String a,String id,boolean ok,String why,String after){OperationAuditSavedData.get(p.serverLevel()).record(p,a,id,ok?"ok":"denied",why,"",after);}private boolean duplicate(ServerPlayer p,long now){for(Alert a:alerts)if(a.targetUuid.equals(p.getUUID().toString())&&OPEN.equals(a.status)&&now-a.time<3000L)return true;return false;}
 public Alert recordDeath(ServerPlayer player, DamageSource source){long now=System.currentTimeMillis();if(duplicate(player,now))return null;Alert a=new Alert();a.id="vital-"+(++sequence);a.status=OPEN;a.deathId=player.getUUID()+":"+now+":"+sequence;a.targetUuid=player.getUUID().toString();a.targetName=player.getScoreboardName();DepartmentPolicy.Identity id=DepartmentPolicy.identity(player);a.department=id.department();a.position=id.position();a.level=id.level();a.time=now;ResourceKey<Level> dim=player.level().dimension();a.dimension=dim.location().toString();BlockPos p=player.blockPosition();a.x=p.getX();a.y=p.getY();a.z=p.getZ();a.damageMsgId=source==null?"unknown":source.getMsgId();a.damageSummary=a.damageMsgId;alerts.add(a);setDirty();return a;}public boolean ack(ServerPlayer p,String id){DepartmentPolicy.Identity u=DepartmentPolicy.identity(p);Alert a=byId(id);boolean ok=a!=null&&OPEN.equals(a.status)&&DepartmentPolicy.DEPT_SECURITY.equals(u.department())&&u.level()>=1&&u.level()<=4;if(ok){a.status=ACKNOWLEDGED;a.ackBy=p.getScoreboardName();a.updatedAt=System.currentTimeMillis();setDirty();}audit(p,"vital_alert_ack",id,ok,"security_1_4",ok?a.status:"");return ok;}public boolean dispatch(ServerPlayer p,String id,String note){DepartmentPolicy.Identity u=DepartmentPolicy.identity(p);Alert a=byId(id);boolean ok=a!=null&&(ACKNOWLEDGED.equals(a.status)||OPEN.equals(a.status))&&(p.hasPermissions(2)||DepartmentPolicy.isFacilityDirector(u.department(),u.position(),u.level())||DepartmentPolicy.isDeptSupervisor(u.department(),u.position(),u.level())||(DepartmentPolicy.DEPT_SECURITY.equals(u.department())&&u.level()>=3&&u.level()<=4));if(ok){a.status=DISPATCHED;a.dispatchBy=p.getScoreboardName();a.note=note==null?"":note.trim();a.updatedAt=System.currentTimeMillis();setDirty();}audit(p,"vital_alert_dispatch",id,ok,"security_3_4_or_supervisor",ok?a.status:"");return ok;}public boolean resolve(ServerPlayer p,String id,String note){DepartmentPolicy.Identity u=DepartmentPolicy.identity(p);Alert a=byId(id);boolean ok=a!=null&&!RESOLVED.equals(a.status)&&(p.hasPermissions(2)||DepartmentPolicy.isFacilityDirector(u.department(),u.position(),u.level())||DepartmentPolicy.isDeptSupervisor(u.department(),u.position(),u.level())||(DepartmentPolicy.DEPT_SECURITY.equals(u.department())&&u.level()>=3&&u.level()<=4));if(ok){a.status=RESOLVED;a.resolvedBy=p.getScoreboardName();a.note=note==null?"":note.trim();a.updatedAt=System.currentTimeMillis();setDirty();}audit(p,"vital_alert_resolve",id,ok,"security_3_4_or_supervisor_or_op",ok?a.status:"");return ok;}
 public JsonObject toJsonFor(ServerPlayer viewer){DepartmentPolicy.Identity u=DepartmentPolicy.identity(viewer);boolean can=DepartmentPolicy.canViewVitalAlerts(u.department(),u.position(),u.level(),viewer.hasPermissions(2));JsonObject root=new JsonObject();JsonArray arr=new JsonArray();if(can)for(Alert a:alerts)arr.add(a.toJson());root.add("items",arr);root.addProperty("skeleton",false);return root;}public static class Alert{public String id="",deathId="",status=OPEN,targetUuid="",targetName="",department="",position="",dimension="",damageMsgId="",damageSummary="",ackBy="",dispatchBy="",resolvedBy="",note="";public int level,x,y,z;public long time,updatedAt;CompoundTag save(){CompoundTag t=new CompoundTag();t.putString("Id",id);t.putString("DeathId",deathId);t.putString("Status",status);t.putString("TargetUuid",targetUuid);t.putString("TargetName",targetName);t.putString("Department",department);t.putString("Position",position);t.putInt("Level",level);t.putString("Dimension",dimension);t.putInt("X",x);t.putInt("Y",y);t.putInt("Z",z);t.putLong("Time",time);t.putLong("UpdatedAt",updatedAt);t.putString("DamageMsgId",damageMsgId);t.putString("DamageSummary",damageSummary);t.putString("AckBy",ackBy);t.putString("DispatchBy",dispatchBy);t.putString("ResolvedBy",resolvedBy);t.putString("Note",note);return t;}static Alert load(CompoundTag t){Alert a=new Alert();a.id=t.getString("Id");a.deathId=t.getString("DeathId");a.status=t.getString("Status");a.targetUuid=t.getString("TargetUuid");a.targetName=t.getString("TargetName");a.department=t.getString("Department");a.position=t.getString("Position");a.level=t.getInt("Level");a.dimension=t.getString("Dimension");a.x=t.getInt("X");a.y=t.getInt("Y");a.z=t.getInt("Z");a.time=t.getLong("Time");a.updatedAt=t.getLong("UpdatedAt");a.damageMsgId=t.getString("DamageMsgId");a.damageSummary=t.getString("DamageSummary");a.ackBy=t.getString("AckBy");a.dispatchBy=t.getString("DispatchBy");a.resolvedBy=t.getString("ResolvedBy");a.note=t.getString("Note");return a;}JsonObject toJson(){JsonObject o=new JsonObject();o.addProperty("id",id);o.addProperty("deathId",deathId);o.addProperty("status",status);o.addProperty("targetUuid",targetUuid);o.addProperty("targetName",targetName);o.addProperty("department",department);o.addProperty("position",position);o.addProperty("level",level);o.addProperty("time",time);o.addProperty("dimension",dimension);o.addProperty("x",x);o.addProperty("y",y);o.addProperty("z",z);o.addProperty("damageMsgId",damageMsgId);o.addProperty("damageSummary",damageSummary);o.addProperty("ackBy",ackBy);o.addProperty("dispatchBy",dispatchBy);o.addProperty("resolvedBy",resolvedBy);o.addProperty("note",note);return o;}}}
